Azure API Management.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Azure API Management container

Container_Boundary(Azure_API_Management, "Azure API Management") {
    Component(API_Gateway, "API Gateway", "Azure API Management (Internal VNet mode)", "Acts as the single secure entry point, handling routing, rate limiting, and dynamic claim-type routing.")
    Component(Security_Validator, "Security Validator", "OAuth 2.0 / OpenID Connect & mTLS", "Validates JWT tokens via Azure Active Directory (Entra ID) and secures service-to-service communication.")
    Component(Telemetry_Publisher, "Telemetry Publisher", "HTTPS", "Publishes telemetry and metrics to Azure Application Insights.")
}

Rel(API_Gateway, Security_Validator, "Validates incoming JWT tokens and secures routing via mTLS", "OAuth 2.0 / mTLS")
Rel(API_Gateway, Telemetry_Publisher, "Publishes metrics and telemetry", "HTTPS")

@enduml

Azure Service Bus.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Azure Service Bus container

Container_Boundary(azure_service_bus, "Azure Service Bus") {
    Component(Service_Bus_Premium_Messaging_Engine, "Service Bus Premium Messaging Engine", "Azure Service Bus Premium Tier, AMQP 1.0, TLS 1.3", "Provides dedicated resources, geo-disaster recovery, and native AMQP 1.0 messaging backbone supporting asynchronous event publishing, queuing, and handling batch processing buffers.")
    Component(Private_Endpoint_Network_Perimeter, "Private Endpoint Network Perimeter", "Azure Private Endpoints", "Restricts network perimeter security by prohibiting public internet access to the message broker.")
    Component(Access_Control_and_Identity_Manager, "Access Control and Identity Manager", "Azure RBAC, Managed Identities, Azure Active Directory (Entra ID)", "Enforces least-privilege access across services, replacing SAS keys for secure interactions.")
}

Rel(Private_Endpoint_Network_Perimeter, Service_Bus_Premium_Messaging_Engine, "Secures network access", "Private IP, TLS 1.3")
Rel(Access_Control_and_Identity_Manager, Service_Bus_Premium_Messaging_Engine, "Authenticates and authorizes access", "Azure RBAC, Managed Identities")
@enduml

Azure SQL Database.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(azure_sql_database, "Azure SQL Database") {
    Component(Claim_Operational_Store, "Claim Operational Store", "Azure SQL Database", "Internal database schema handling CRUD operations and high-frequency lookups for claims.")
    Component(Migration_State___Routing_Registry, "Migration State & Routing Registry", "Azure SQL Database", "Internal database schema tracking the hybrid migration state and routing of claim types.")
    Component(Audit___Reconciliation_Log, "Audit & Reconciliation Log", "Azure SQL Database", "Internal database schema storing audit trails and reconciliation logs for compliance.")
}

Rel(Claim_Operational_Store, Migration_State___Routing_Registry, "Maintains relational integrity and routing metadata")
Rel(Migration_State___Routing_Registry, Audit___Reconciliation_Log, "Logs migration state transitions and reconciliation events")
@enduml

Azure Active Directory (Entra ID).diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(azure_active_directory_entra_id, "Azure Active Directory (Entra ID)") {
    Component(Token_Service_STS, "Token Service (STS)", "OAuth 2.0 / OpenID Connect (OIDC)", "Issues and validates security tokens, and provides public JWKS endpoints.")
    Component(Directory_Graph_API_Component, "Directory & Graph API Component", "Microsoft Graph API", "Manages directory data and user identity information.")
    Component(B2C_External_Identity_Federation_Gateway, "B2C / External Identity Federation Gateway", "Azure AD B2C", "Handles external identity federation for customers and brokers.")
    Component(Audit_Reporting_Component, "Audit & Reporting Component", "Azure Monitor / Log Analytics", "Monitors sign-in and audit telemetry.")
}

Rel(Token_Service_STS, Claims_Processing_Service, "Provides JWT tokens and public JWKS endpoints", "HTTPS")
Rel(Token_Service_STS, Azure_API_Management, "Provides OIDC metadata and JWKS for edge token validation", "HTTPS")
Rel(Audit_Reporting_Component, Azure_Application_Insights, "Ingests telemetry using Azure Diagnostic Settings", "HTTPS")

@enduml
